// Standalone installed NativeSDK consumer. No private headers, parser fallback,
// Python runtime, image-reader plugin or source-checkout linkage is required.
#include <qupathxx/format_import.hpp>
#include <qupathxx/file_fingerprint.hpp>
#include <qupathxx/object_properties.hpp>
#include <qupathxx/project.hpp>
#include <qupathxx/raw_image.hpp>
#include <qupathxx/workflow.hpp>
#include <array>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <vector>
