#endif
namespace fs=std::filesystem;
using namespace qpx;
namespace {
void check(bool b,const std::string& m){if(!b)throw std::runtime_error(m);}
template<class F>std::string refuses(F&& f){try{f();}catch(const std::exception& e){return e.what();}throw std::runtime_error("Expected installed native provider refusal");}
std::string bytes(const fs::path& p){std::ifstream in(p,std::ios::binary);check(bool(in),"Read installed-route retained evidence");return {std::istreambuf_iterator<char>(in),{}};}
void write(const fs::path& p,const std::string& s){std::ofstream out(p,std::ios::binary);out<<s;out.close();check(bool(out),"Save installed-route evidence");}
MatrixPluginImportOptions options(){MatrixPluginImportOptions o;o.frame.id="literal-positions";o.frame.source_id="authored-position-frame";o.frame.unit=CoordinateUnit::Pixel;o.limits.work_bytes=32u*1024*1024;o.plugin_work_bytes=1u*1024*1024;return o;}
std::shared_ptr<Document> document(const fs::path& fixtures){auto server=open_tiff((fixtures/"image.tif").u8string());const auto metadata=server->raw_metadata();check(metadata&&metadata->width==16&&metadata->height==16&&metadata->channels==3&&metadata->z_planes==1&&metadata->timepoints==1&&metadata->sample_type==SampleType::UInt8&&server->raw_view(),"Installed quantitative TIFF metadata differs");RawRegionRequest control;control.region={0,0,0,16,16};control.channels=3;const auto raw=server->read_raw(control);check(std::get<std::vector<std::uint8_t>>(raw.storage())==std::vector<std::uint8_t>(768,80)&&raw.valid()==std::vector<std::uint8_t>(256,1),"Installed quantitative TIFF literal samples differ");auto d=std::make_shared<Document>(std::move(server));d->set_class_definition(ObjectClass::definition("Native Tumor",0x123456));d->set_class_definition(ObjectClass::definition("Native Stroma",0x654321));d->add_rectangle({12,12,1,1},"Sentinel");d->clear_history();return d;}
AnnotationPluginImportOptions annotation_options(){AnnotationPluginImportOptions o;o.class_map={{"T","Native Tumor"},{"S","Native Stroma"}};return o;}
void matrix_exact(const ExpressionMatrixSource& source){check(source.metadata().features==3&&source.metadata().observations==3&&source.metadata().entries==9&&source.metadata().input_profile=="external-dense-counts/1","Installed QMX profile/shape differs");check(source.feature_page(0,3).at(0).id=="0002"&&source.observation_page(0,3)==std::vector<std::string>{"0001","1","18446744073709551615"},"Installed QMX axis identity differs");ExpressionMatrixSelection q;q.features={0,1,2};const auto b=source.read(q);check(b.offsets==std::vector<std::uint64_t>{0,3,6,9}&&b.observation_indices==std::vector<std::uint64_t>{0,1,2,0,1,2,0,1,2}&&b.counts==std::vector<std::uint64_t>{UINT64_MAX,0,11,UINT64_C(9007199254740993),7,0,0,0,0},"Installed native UInt64 values/explicit zeros changed");const auto positions=source.spatial_page(0,3);for(unsigned i=0;i<3;++i)check(positions.at(i).position.x==10.25+10*i&&positions.at(i).position.y==20.5+10*i,"Installed native position join differs");}
void point_exact(const Document& d){check(d.object_count()==4&&d.annotation(1).name=="Sentinel","Saved installed document membership changed");const std::array<std::string,3> ids={"0001","1","18446744073709551615"},classes={"Native Tumor","","Native Stroma"};for(unsigned i=0;i<3;++i){const auto a=d.annotation(i+2);check(a.name==ids[i]&&a.geometry.equals(Roi::points({{1.25+i,2.5+i}}))&&a.plane==ObjectPlane(i==1?0:-1,0,0)&&a.class_name==classes[i]&&a.properties,"Saved installed point geometry/plane/class differs");const auto& p=a.properties->metadata();check(p.at("qpx.annotation-plugin.schema")=="qpx.annotation-plugin-object/1"&&p.at("qpx.annotation-plugin.source_id")==ids[i]&&p.at("qpx.annotation-plugin.native_class")==classes[i]&&p.at("qpx.annotation-plugin.provider_id")=="org.qupathxx.point-tsv"&&p.at("qpx.annotation-plugin.source_row")==std::to_string(i),"Source ID/native ID association did not persist");}}
void create(const fs::path& fixtures,const fs::path& w){const auto f=w/"source-files";fs::create_directory(f);for(const auto* name:{"counts-main.tsv","positions.tsv","points-main.tsv"})fs::copy_file(fixtures/name,f/name);const auto r=import_expression_matrix_plugin("org.qupathxx.counts-tsv",(f/"counts-main.tsv").u8string(),(f/"positions.tsv").u8string(),(w/"counts.qmx").u8string(),options());auto source=open_expression_matrix(r.path,r.file_sha256);matrix_exact(*source);const auto receipt=external_expression_matrix_receipt(*source);check(bool(receipt),"Missing installed external receipt");write(w/"matrix.receipt.json",format_plugin_receipt_json(receipt->reader));write(w/"matrix.sha256",r.file_sha256);write(w/"matrix-source.sha256",r.metadata.source_sha256);auto d=document(fixtures);auto p=preview_annotation_plugin(*d,"org.qupathxx.point-tsv",(f/"points-main.tsv").u8string(),annotation_options());const auto applied=apply_annotation_plugin(*d,p);check(p.consumed()&&applied.objects.size()==3&&applied.objects[0].source_id=="0001"&&applied.objects[0].object_id==2,"Installed source/native mapping");point_exact(*d);write(w/"annotation.receipt.json",format_plugin_receipt_json(applied.receipt));Project project;check(project.add_document(d,"Typed points")==1,"Installed native image ID");project.save((w/"points.qpproj").u8string());}
void reopen(const fs::path& w){auto source=open_expression_matrix((w/"counts.qmx").u8string(),bytes(w/"matrix.sha256"));matrix_exact(*source);const auto receipt=external_expression_matrix_receipt(*source);check(receipt&&format_plugin_receipt_json(receipt->reader)==bytes(w/"matrix.receipt.json")&&source->metadata().source_sha256==bytes(w/"matrix-source.sha256"),"Retained exact external provenance changed");auto project=Project::open((w/"points.qpproj").u8string());point_exact(*project->document(1));const auto r=parse_format_plugin_receipt(bytes(w/"annotation.receipt.json"));for(unsigned i=0;i<3;++i)check(project->document(1)->annotation(i+2).properties->metadata().at("qpx.annotation-plugin.receipt_sha256")==format_plugin_receipt_identity(r),"Retained object receipt changed");}
void offline(const fs::path& f,const fs::path& w){check(format_plugin_infos().empty(),"Offline fresh process unexpectedly has typed providers");fs::rename(w/"source-files",w/"source-files-unavailable");check(!fs::exists(w/"source-files"),"Original source files are still available");reopen(w);const auto path=w/"offline-never.qmx";const auto m=refuses([&]{import_expression_matrix_plugin("org.qupathxx.counts-tsv",(f/"counts-main.tsv").u8string(),(f/"positions.tsv").u8string(),path.u8string(),options());});check(m.find("Format plugin provider unavailable: org.qupathxx.counts-tsv")!=std::string::npos&&!fs::exists(path),"Fresh missing-provider matrix did not reach actual provider lookup");auto d=document(f);const auto before=d->revision();const auto a=refuses([&]{preview_annotation_plugin(*d,"org.qupathxx.point-tsv",(f/"points-main.tsv").u8string(),annotation_options());});check(a.find("Format plugin provider unavailable: org.qupathxx.point-tsv")!=std::string::npos&&d->revision()==before&&d->object_count()==1&&!d->can_undo(),"Fresh missing-provider point lookup mutated document or refused for wrong reason");}
void changed_implementation(const fs::path& f,const fs::path& w){reopen(w);const auto old=parse_format_plugin_receipt(bytes(w/"matrix.receipt.json"));const auto r=import_expression_matrix_plugin("org.qupathxx.counts-tsv",(f/"counts-main.tsv").u8string(),(f/"positions.tsv").u8string(),(w/"different-module.qmx").u8string(),options());const auto receipt=external_expression_matrix_receipt(*open_expression_matrix(r.path,r.file_sha256));check(receipt&&receipt->reader.source_sha256==old.source_sha256&&receipt->reader.provider.version==old.provider.version&&receipt->reader.provider.module_sha256!=old.provider.module_sha256&&receipt->reader.provider.implementation_sha256!=old.provider.implementation_sha256&&r.metadata.source_sha256!=bytes(w/"matrix-source.sha256"),"Changed implementation was aliased by same provider/version/source");reopen(w);}
void cli_reopen(const fs::path& w){auto source=open_expression_matrix((w/"cli-counts.qmx").u8string());matrix_exact(*source);check(source->metadata().spatial_frame&&source->metadata().spatial_frame->id=="qpx.format-import-cli-image/1"&&source->metadata().spatial_frame->image_level_zero&&source->metadata().spatial_frame->width==16&&source->metadata().spatial_frame->height==16,"CLI image coordinate frame differs");const auto receipt=external_expression_matrix_receipt(*source);check(receipt&&receipt->reader.provider.provider_id=="org.qupathxx.counts-tsv","CLI QMX has no typed native receipt");auto old=Project::open((w/"points.qpproj").u8string())->document(1);auto fresh=Project::open((w/"cli-points.qpproj").u8string())->document(1);check(fresh->object_count()==7&&fresh->classes()==old->classes(),"CLI point publication lost existing objects/classes");for(const auto& [id,a]:old->objects()){const auto b=fresh->annotation(id);check(a.name==b.name&&a.geometry.equals(b.geometry)&&a.plane==b.plane&&a.class_name==b.class_name&&bool(a.properties)==bool(b.properties),"CLI publication changed existing object");if(a.properties)check(a.properties->equals(*b.properties),"CLI publication changed existing properties");}for(unsigned i=0;i<3;++i){const auto a=fresh->annotation(5+i),b=old->annotation(2+i);check(a.id!=b.id&&a.name==b.name&&a.geometry.equals(b.geometry)&&a.plane==b.plane&&a.class_name==b.class_name&&a.properties->metadata().at("qpx.annotation-plugin.source_id")==b.name,"CLI appended source/native ID mapping changed");}}
void changed_source(const fs::path& f,const fs::path& w){auto d=document(f);const auto path=w/"change-points.tsv";write(path,bytes(f/"points-main.tsv"));auto p=preview_annotation_plugin(*d,"org.qupathxx.point-tsv",path.u8string(),annotation_options());const auto stable=p.receipt().source_sha256;check(p.objects().size()==3&&!p.consumed(),"Valid source control failed before mutation");auto text=bytes(path);text.replace(text.find("0001"),4,"0002");write(path,text);const auto revision=d->revision();bool refused=false;try{apply_annotation_plugin(*d,p);}catch(const WorkflowInputChanged&){refused=true;}check(refused&&!p.consumed()&&d->revision()==revision&&d->object_count()==1&&!d->can_undo(),"Changed source did not refuse exact currentness atomically");auto fresh=preview_annotation_plugin(*d,"org.qupathxx.point-tsv",path.u8string(),annotation_options());check(fresh.receipt().source_sha256!=stable&&fresh.sha256()!=p.sha256()&&fresh.objects()[0].name=="0002","Fresh changed-source capture aliases old source");reopen(w);}
int dispatch(int argc,char** argv){try{if(argc!=5)throw std::invalid_argument("Usage: MODE MANIFEST|- FIXTURES WORK");const std::string mode=argv[1];const auto f=fs::absolute(fs::u8path(argv[3])),w=fs::absolute(fs::u8path(argv[4]));if(mode!="offline")configure_format_plugins(fs::absolute(fs::u8path(argv[2])).u8string());if(mode=="create")create(f,w);else if(mode=="reopen")reopen(w);else if(mode=="offline")offline(f,w);else if(mode=="changed-implementation")changed_implementation(f,w);else if(mode=="changed-source")changed_source(f,w);else if(mode=="cli-reopen")cli_reopen(w);else throw std::invalid_argument("Unknown SDK typed-provider mode");std::cout<<"Installed native format consumer "<<mode<<" passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
}
#ifdef _WIN32
int wmain(int argc,wchar_t** argv){std::vector<std::string> owned;std::vector<char*> utf8;for(int i=0;i<argc;++i){const int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,argv[i],-1,nullptr,0,nullptr,nullptr);if(n<=0)return 2;std::string s(static_cast<std::size_t>(n),'\0');if(!WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,argv[i],-1,s.data(),n,nullptr,nullptr))return 2;s.pop_back();owned.push_back(std::move(s));}for(auto& s:owned)utf8.push_back(s.data());return dispatch(argc,utf8.data());}
#else
int main(int argc,char** argv){return dispatch(argc,argv);}
#endif
